def countFactorialsWithZeros(k):
    def zeros(n):
        c = 0
        while n:
            n //= 5
            c += n
        return c

    lo, hi = 0, 5 * (k + 1)
    while lo < hi:
        mid = (lo + hi) // 2
        if zeros(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return 5 if zeros(lo) == k else 0
